"$path = "$env:USERPROFILE\.gemini\antigravity\brain\6768435f-eb70-4e50-a228-092414afb636\.system_generated\logs\transcript.jsonl"
if (Test-Path $path) {
    Write-Host "Found transcript.jsonl at $path"
    $lines = Get-Content $path -Encoding UTF8
    foreach ($line in $lines) {
        try {
            $obj = ConvertFrom-Json $line
            # We want CODE_ACTION steps, and maybe others that run tools
            if ($obj.tool_calls) {
                foreach ($tc in $obj.tool_calls) {
                    $args = $tc.arguments
                    if ($args.TargetFile -like "*index.html*") {
                        $step = $obj.step_index
                        Write-Host "Step $step: Tool: $($tc.name)"

                        if ($args.ReplacementContent) {
                            $outPath = "scratch_step_${step}_replacement.txt"
                            $args.ReplacementContent | Out-File -FilePath $outPath -Encoding utf8
                            Write-Host "  Saved ReplacementContent to $outPath"
                        }
                        if ($args.CodeContent) {
                            $outPath = "scratch_step_${step}_code.txt"
                            $args.CodeContent | Out-File -FilePath $outPath -Encoding utf8
                            Write-Host "  Saved CodeContent to $outPath"
                        }
                        if ($args.ReplacementChunks) {
                            $chunkIdx = 0
                            foreach ($chunk in $args.ReplacementChunks) {
                                $outPath = "scratch_step_${step}_chunk_${chunkIdx}.txt"
                                $chunk.ReplacementContent | Out-File -FilePath $outPath -Encoding utf8
                                Write-Host "  Saved Chunk $chunkIdx to $outPath"
                                $chunkIdx++
                            }
                        }
                    }
                }

